mapper.sql:
select po.id, pod.id as purchaseDetailId, po.approve_time approveTime, pod.execution_status as executionStatus, pod.confirm_type as confirmType, po.purchase_org_name as purchaseOrgName, po.type as type, po.code, pos.supplier_name as supplierName, po.approve_status as approveStatus, po.invalid_status as invalidStatus, pod.execution_status as executionStatus, pod.sku_id as skuId, pod.sku_no as skuNo, pod.product_name as productName, pod.variant_property as variantProperty, pod.plan_delivery_date as planDeliveryDate, pod.is_urgent as isUrgent, po.delivery_warehouse_name as deliveryWarehouseName, pod.tax_price as taxPrice, pod.tax_rate as taxRate, pod.currency_symbol as currencySymbol, pod.purchase_qty as purchaseQty, pod.purchase_amount as purchaseAmount, pod.remark, po.subcontract_type as subcontractType, po.approve_user_name as approveUserName, po.purchase_user_name as purchaseUserName, po.create_user_name as createUserName, po.create_time as createTime, pod.is_end_receive as isEndReceive, pod.end_receive_time as endReceiveTime, so.code as subContractCode, case when pod.plan_delivery_date is not null then date_part('day', pod.plan_delivery_date::timestamp - CURRENT_DATE::timestamp) else null end AS deliveryCycle, po.source_id as sourceId, po.source_type as sourceType from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false left join subcontract_order so on so.id = po.source_id and so.is_deleted = false
${params.sqlMap.default}
and po.is_deleted = false
and pos.supplier_id = #{params.supplierId}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
po.approve_time DESC

select po.id, pod.id as purchaseDetailId, po.approve_time approveTime, pod.execution_status as executionStatus, pod.confirm_type as confirmType, po.purchase_org_name as purchaseOrgName, po.type as type, po.code, pos.supplier_name as supplierName, po.approve_status as approveStatus, po.invalid_status as invalidStatus, pod.execution_status as executionStatus, pod.sku_id as skuId, pod.sku_no as skuNo, pod.product_name as productName, pod.variant_property as variantProperty, pod.plan_delivery_date as planDeliveryDate, pod.is_urgent as isUrgent, po.delivery_warehouse_name as deliveryWarehouseName, pod.tax_price as taxPrice, pod.tax_rate as taxRate, pod.currency_symbol as currencySymbol, pod.purchase_qty as purchaseQty, pod.purchase_amount as purchaseAmount, pod.remark, po.subcontract_type as subcontractType, po.approve_user_name as approveUserName, po.purchase_user_name as purchaseUserName, po.create_user_name as createUserName, po.create_time as createTime, pod.is_end_receive as isEndReceive, pod.end_receive_time as endReceiveTime, so.code as subContractCode, case when pod.plan_delivery_date is not null then date_part('day', pod.plan_delivery_date::timestamp - CURRENT_DATE::timestamp) else null end AS deliveryCycle, po.source_id as sourceId, po.source_type as sourceType from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false left join subcontract_order so on so.id = po.source_id and so.is_deleted = false
${params.sqlMap.default}
and po.is_deleted = false and po.approve_status = 'approve'
and pos.supplier_id = #{params.supplierId}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
planDeliveryDate ASC

mapper.select:
select po.id, pod.id as purchaseDetailId, po.type as type, po.code, pos.supplier_id as supplierId, pos.supplier_name as supplierName, po.approve_status as approveStatus, po.invalid_status as invalidStatus, pod.execution_status as executionStatus, pod.confirm_remark as confirmRemark, pod.sku_id as skuId, pod.sku_no as skuNo, pod.product_name as productName, pod.variant_property as variantProperty, pod.plan_delivery_date as planDeliveryDate, pod.is_urgent as isUrgent, po.delivery_warehouse_name as deliveryWarehouseName, pod.tax_price as taxPrice, pod.tax_rate as taxRate, pod.currency_symbol, pod.purchase_qty as purchaseQty, pod.purchase_amount as purchaseAmount, pod.remark, po.subcontract_type as subcontractType, po.approve_user_name as approveUserName, po.approve_time as approveTime, po.purchase_user_name as purchaseUserName, po.create_user_name as createUserName, po.create_time as createTime, pod.is_end_receive as isEndReceive, pod.end_receive_time as endReceiveTime, so.code as subContractCode, po.source_id as sourceId, po.source_type as sourceType, pod.warehouse_location as warehouseLocation, po.contract_stamp_status as contractStampStatus from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false left join subcontract_order so on so.id = po.source_id and so.is_deleted = false
${params.sqlMap.default} and po.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
po.id desc,pod.id asc

select COALESCE(sum(pod.purchase_qty),0) as totalQty, COALESCE(sum(pod.purchase_amount),0) as totalAmount from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false left join subcontract_order_detail sod on pod.source_detail_id = sod.id and sod.is_deleted = false left join subcontract_order so on so.id = sod.main_id and so.is_deleted = false
${params.sqlMap.default} and po.is_deleted = false
${params.permissionSql}

select po.id, pod.id as purchaseDetailId, po.type as type, po.code, pos.supplier_id as supplierId, pos.supplier_name as supplierName, po.approve_status as approveStatus, po.invalid_status as invalidStatus, pod.execution_status as executionStatus, pod.sku_id as skuId, pod.sku_no as skuNo, pod.product_name as productName, pod.variant_property as variantProperty, pod.plan_delivery_date as planDeliveryDate, pod.is_urgent as isUrgent, po.delivery_warehouse_name as deliveryWarehouseName, pod.tax_price as taxPrice, pod.tax_rate as taxRate, pod.purchase_qty as purchaseQty, pod.purchase_amount as purchaseAmount, pod.remark, po.approve_user_name as approveUserName, po.approve_time as approveTime, po.purchase_user_name as purchaseUserName, po.create_user_name as createUserName, po.create_time as createTime, pod.is_end_receive as isEndReceive, pod.end_receive_time as endReceiveTime, so.code as subContractCode, po.source_id as sourceId, po.source_type as sourceType, pod.warehouse_location as warehouseLocation from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false left join subcontract_order_detail sod on pod.source_detail_id = sod.id and sod.is_deleted = false left join subcontract_order so on so.id = sod.main_id and so.is_deleted = false where ${params.sqlMap.default} and po.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
po.create_time desc

select count(po.id) from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false left join subcontract_order so on so.id = po.source_id and so.is_deleted = false
${params.sqlMap.default} and po.is_deleted = false
${params.permissionSql}

SELECT po.id AS id, pod.id as purchaseOrderDetailId, po.code AS code, pos.supplier_id as supplierId, pos.supplier_name AS supplierName, po.delivery_warehouse_id as deliveryWarehouseId, po.delivery_warehouse_name AS deliveryWarehouseName, pod.sku_id AS skuId, pod.sku_no AS skuNo, '' AS productName, pod.plan_delivery_date AS planDeliveryDate, '' AS receiveUserId, '' AS receiveUserName, pod.purchase_qty AS purchaseQty, 0 as unReceiveQty, 0 as receiveQty, 0 as exceedQty, pod.first_mass_product as firstMassProduct FROM purchase_order po INNER JOIN purchase_order_detail pod ON pod.purchase_order_id = po.id AND po.is_deleted = FALSE LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po."id" AND pod.is_deleted = FALSE WHERE pos.is_deleted = FALSE
AND pod.id in
#{item}

SELECT po.id AS purchaseOrderId, po.code, ps.supplier_id, po.receive_org_id, po.purchase_org_id, ps.supplier_name, po.delivery_warehouse_id, po.delivery_warehouse_name FROM purchase_order po INNER JOIN purchase_order_supplier ps ON ps.purchase_order_id=po.id AND ps.is_deleted=false WHERE po.is_deleted=false
AND po.id IN
#{item}

select po.code, s.name as supplierName, po.approve_status as approveStatus, pod.sku_id as skuId, pod.sku_no as skuNo, pod.plan_delivery_date as planDeliveryDate, po.delivery_warehouse_name as deliveryWarehouseName, po.purchase_user_name as purchaseUserName, so.code as subContractCode, pod.purchase_qty as purchaseQty from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false inner join subcontract_order_detail sod on pod.source_detail_id = sod.id and sod.is_deleted = false inner join subcontract_order so on so.id = sod.main_id and so.is_deleted = false left join supplier s on sod.supplier_id = s.id and s.is_deleted = false
po.is_deleted = false and po.invalid_status = false
and sod.main_id = #{sourceId}

SELECT T.sku_id as skuId, T."sku_no" AS skuNo, T."LatestPurchaseDate" AS costDate, D.tax_price as costPrice, D.tax_price/( 1 + D.tax_rate) as notTaxCostPrice, D.purchase_qty as qty, D.currency, CAST(T."LatestPurchaseDate" - INTERVAL '3 months' AS DATE) AS threeMonthsAgoDate, CAST(T."LatestPurchaseDate" AS DATE) AS latestPurchaseDate FROM ( SELECT pod.sku_id, pod.sku_no, MAX(po.purchase_date) AS "LatestPurchaseDate" FROM purchase_order po LEFT JOIN purchase_order_detail pod ON po.id = pod.purchase_order_id AND pod.is_deleted = FALSE LEFT JOIN purchase_order_supplier pos ON po.id = pos.purchase_order_id AND pos.is_deleted = FALSE WHERE po.is_deleted = FALSE and po.type = 'CGDD01_SYS' and po.invalid_status = false and po.approve_status = 'approve'
AND pod.sku_id in
#{item}
AND pod.sku_no in
#{item}
AND po.id not in
#{id}
AND pos.supplier_id not in
#{id}
GROUP BY pod.sku_no ,pod.sku_id ) AS T JOIN purchase_order S LEFT JOIN purchase_order_detail D ON S.id = D.purchase_order_id AND D.is_deleted = FALSE ON T."sku_no" = D."sku_no" AND S."purchase_date" >= T."LatestPurchaseDate" - INTERVAL '3 months' LEFT JOIN purchase_order_supplier P ON S.id = P.purchase_order_id AND P.is_deleted = FALSE WHERE S.is_deleted = false and S.type = 'CGDD01_SYS' and S.invalid_status = false and S.approve_status = 'approve'
AND S.id not in
#{id}
AND P.supplier_id not in
#{id}

select EXTRACT(MONTH FROM po.approve_time) as month, count(distinct po.id) as orderCount, sum(pod.purchase_qty) as orderSkuCount, sum(pod.purchase_amount) as orderMoney from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false where pos.supplier_id = #{params.supplierId}
and po.approve_time >= #{params.startTime}
and po.approve_time <= #{params.endTime}
and pod.is_deleted = false and po.approve_status = 'approve' and po.is_deleted = false group by EXTRACT(MONTH FROM po.approve_time)

select
    count(distinct po.id)
from purchase_order po
         left join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false
         left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pod.is_deleted = false
where pos.supplier_id = #{params.supplierId}

    AND pod.execution_status = #{params.executionStatus}


    AND po.approve_status = #{params.approveStatus}

select po.id, po.code from purchase_order po
po.is_deleted = false
${params.permissionSql}
and (po.id = #{params.searchKeyword} or po.code ilike concat('%',#{params.searchKeyword}::text,'%'))
and po.approve_status = #{params.approveStatus}

select po.id, pod.id as purchaseDetailId, po.code, pos.supplier_id as supplierId, pod.sku_id as skuId, pod.sku_no as skuNo, pod.purchase_qty as purchaseQty, po.create_time as createTime from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false where po.invalid_status = false and po.is_deleted = false
AND pod.sku_id IN
#{item}
AND pos.supplier_id IN
#{item}

SELECT DISTINCT pos.supplier_id, pod.sku_no FROM purchase_order_supplier AS pos INNER JOIN purchase_order AS po ON pos.purchase_order_id = po.ID AND po.approve_status = 'approve' AND po.is_deleted = FALSE INNER JOIN purchase_order_detail AS pod ON pod.purchase_order_id = po.ID AND pod.is_deleted = FALSE WHERE pos.is_deleted = FALSE
AND pos.supplier_id IN
#{item}

WITH productDetailGroup AS ( SELECT purchase_order_id, sku_id, SUM(purchase_qty) AS original_total FROM purchase_order_detail where is_deleted = false and is_gift = false group by purchase_order_id,sku_id ) select po.id, po.code, po.purchase_date as purchaseDate, po.approve_status as approveStatus, ps.supplier_id as supplierId, pod.id as detailId, pod.execution_status as executionStatus, po.purchase_org_id as purchaseOrgId, pod.sku_id as skuId, pod.sku_no as skuNo, pd.name as productName, pod.purchase_qty as purchaseQty, pod.tax_rate as taxRate, pod.tax_price as taxPrice, pod.currency, pod.currency_symbol as currencySymbol, pod.create_time as createTime from purchase_order po inner join purchase_order_supplier ps on po.id = ps.purchase_order_id and ps.is_deleted = false inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false inner join productDetailGroup pdg on pod.purchase_order_id = pdg.purchase_order_id and pod.sku_id = pdg.sku_id left join product_detail pd on pod.sku_id = pd.id and pd.is_deleted = false
${params.sqlMap.default} and po.is_deleted = false and po.invalid_status = false and pod.execution_status not in ('finish','closed') and pod.is_gift = false
and ps.supplier_id = #{params.supplierId}
and pod.sku_id = #{params.skuId}
and pdg.original_total >= #{params.minQty}
and pdg.original_total < #{params.maxQty}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
po.create_time desc
